function main(p, state) {
  const slots = (state.inventory && state.inventory.slots) || [];
  const plankRe = /^minecraft:[a-z_]+_planks$/;
  const stickRe = /^minecraft:stick$/;
  const logRe = /^minecraft:(stripped_)?[a-z_]+(_log|_wood|_stem|_hyphae)$/;
  const bambooRe = /^minecraft:(stripped_)?bamboo_block$/;
  let planks = 0, sticks = 0, logs = 0;
  const pm = {}, lm = {};
  for (let i = 0; i < slots.length; i++) {
    const s = slots[i];
    if (!s || !s.id) continue;
    const n = s.count || 0;
    if (plankRe.test(s.id)) { planks += n; pm[s.id] = (pm[s.id] || 0) + n; }
    else if (stickRe.test(s.id)) { sticks += n; }
    else if (logRe.test(s.id) || bambooRe.test(s.id)) { logs += n; lm[s.id] = (lm[s.id] || 0) + n; }
  }
  function toList(m) {
    const out = [];
    for (const k in m) out.push({ id: k, count: m[k] });
    return out;
  }
  return { planks: planks, sticks: sticks, logs: logs, plankIds: toList(pm), logIds: toList(lm) };
}
